<?php require_once __DIR__.'/../app/db.php'; require_once __DIR__.'/../app/helpers.php'; require_once __DIR__.'/../app/auth.php'; try{ migrate(); }catch(Exception $e){} if(user()) redirect('/index.php'); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $pdo=pdo(); $stmt=$pdo->prepare('SELECT * FROM users WHERE identifiant=? AND actif=1'); $stmt->execute([post('identifiant')]); $u=$stmt->fetch(); if($u && password_verify(post('mot_de_passe'),$u['mot_de_passe'])){ $_SESSION['user']=['id'=>$u['id'],'nom'=>$u['nom'],'identifiant'=>$u['identifiant'],'role'=>$u['role']]; log_action('Connexion','Utilisateur '.$u['identifiant']); redirect('/index.php'); } $err='Identifiant ou mot de passe incorrect.'; }
